Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.
#[local] Abbreviation cellA := (cell AsanUbsan.M.loaded_segments).
#[local] Abbreviation wrA := (wr AsanUbsan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Definition art_sec_events (msz r parr nch : Z) (committed : bool) : list aev := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S20!1,6+3|30;$msz;R+0$r;R+0$parr;R+0$nch;R+0$committed;R+1!3,2+3!2,4#5#4-1RN$committed;R+1!1+5+3#120!3,2+3!2,7!2'8#3!2'9!1,:1#2!1,:|A00000;0").

(* [comment removed for export] *)
Definition art_sec_fp (s t parr nch r msz : Z) (committed : bool) : list (Z * Z) :=
  [ (s - 464, 464); (0x16a198, 624); (0x16a408 + 16, 16); (t + 2872, 16); (r, msz); (art_shlo r, art_shhi r msz - art_shlo r);
    (parr + 8 * nch, if committed then 8 else 131072) ].

(* [comment removed for export] *)
Definition art_sec_grant (HI t ctx parr msz r : Z) : Prop :=
  r mod 4096 = 0 /\ 4096 <= r /\ 0x6c4000 <= r /\ r + msz <= HI /\ appmem r msz
  /\ apart r msz t 4096 /\ apart r msz ctx 4096 /\ apart r msz parr (2 ^ 23).

Lemma art_at_ecall_mmap2 : art_at_ecall ASEGS (0x94afc : word).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40|500;!1+<!1,=0!1+@1!2'A'B!3,C!1,=|600;!1,:|C14afc;,D!4,;1$w;R1!2+>!3+?23!2,E1#1!3+?+1!1'F#1,G'H!4,I!3+?23!2,E1'H!3+?+1!1'F'H,G'J'K").
Qed.

(* [comment removed for export] *)
Lemma art_sh_bounds : forall r msz, r mod 4096 = 0 -> msz mod 4096 = 0 -> 0 <= r -> 0 <= msz -> r + msz <= 2 ^ 47 ->
